#!/usr/bin/env python3
"""Compute bootstrap 95% CI for GAR/PPL metrics from eval JSON results.

Supports 3 JSON formats:
  1. Standard GAR eval: gar_curves[[turn1, turn2, ...], ...], ppl_per_conversation
  2. Attention steering: results.beta_X.{per_conv_mid_gar, ppl_per_conversation}
  3. Phase 1 diagnostic: conversations[].gar_per_turn[]

Usage:
    python scripts/compute_bootstrap_ci.py runs/4way_eval/tg_v7_ours/phase2_tg_s42_v7_gar.json
    python scripts/compute_bootstrap_ci.py runs/attention_steering/attention_steering_gen_n50_fixed.json
    python scripts/compute_bootstrap_ci.py runs/eval_v7_tg_s123/ar_tg_ours/epoch_2_gar.json runs/eval_v7_tg_s123/ar_base_ours/base_model_gar.json
"""
import json, sys, argparse
import numpy as np
from pathlib import Path


def bootstrap_ci(values, n_boot=10000, ci=95, seed=42):
    """Bootstrap confidence interval for mean."""
    rng = np.random.RandomState(seed)
    values = np.array(values, dtype=float)
    n = len(values)
    boot_means = np.array([
        np.mean(rng.choice(values, n, replace=True)) for _ in range(n_boot)
    ])
    lo = np.percentile(boot_means, (100 - ci) / 2)
    hi = np.percentile(boot_means, 100 - (100 - ci) / 2)
    return {
        "mean": float(np.mean(values)),
        "median": float(np.median(values)),
        "std": float(np.std(values, ddof=1)) if n > 1 else 0.0,
        "ci_lo": float(lo),
        "ci_hi": float(hi),
        "n": n,
    }


def extract_per_conv_mid_gar(data, min_turns=3):
    """Extract per-conversation mid-turn GAR from gar_curves.

    Mid-turns = turns with index >= 2 (i.e., turn 3 onwards).
    Returns list of per-conversation mean mid-turn GAR.
    """
    curves = data.get("gar_curves", [])
    per_conv = []
    for c in curves:
        if len(c) >= min_turns:
            per_conv.append(float(np.mean(c[2:])))
    return per_conv


def fmt(stat, label=""):
    """Format a bootstrap stat dict as one line."""
    prefix = f"  {label}: " if label else "  "
    return (
        f"{prefix}mean={stat['mean']:.4f}, median={stat['median']:.4f}, "
        f"std={stat['std']:.4f}, 95% CI=[{stat['ci_lo']:.4f}, {stat['ci_hi']:.4f}], "
        f"n={stat['n']}"
    )


def process_standard(data, fpath, n_boot, seed):
    """Process standard GAR eval format (gar_curves + optional ppl)."""
    print(f"\n=== {Path(fpath).name} ===")
    meta = []
    for k in ("checkpoint_dir", "gate_type", "gar_variant", "num_conversations", "num_turns"):
        if k in data:
            meta.append(f"{k}={data[k]}")
    if meta:
        print(f"  [{', '.join(meta)}]")

    if "mid_turns_avg_gar" in data:
        print(f"  mid_turns_avg_gar (precomputed): {data['mid_turns_avg_gar']:.6f}")

    per_conv = extract_per_conv_mid_gar(data)
    if per_conv:
        stat = bootstrap_ci(per_conv, n_boot=n_boot, seed=seed)
        print(fmt(stat, "mid-turn GAR (per-conv)"))

    all_mid = []
    for c in data.get("gar_curves", []):
        if len(c) >= 3:
            all_mid.extend(c[2:])
    if all_mid:
        stat = bootstrap_ci(all_mid, n_boot=n_boot, seed=seed)
        print(fmt(stat, "mid-turn GAR (pooled)"))

    if "avg_gar_per_turn" in data:
        avg = data["avg_gar_per_turn"]
        turns_str = ", ".join(f"t{i+1}={v:.4f}" for i, v in enumerate(avg))
        print(f"  avg_gar_per_turn: [{turns_str}]")

    if "ppl_per_conversation" in data:
        ppl_vals = data["ppl_per_conversation"]
        stat = bootstrap_ci(ppl_vals, n_boot=n_boot, seed=seed)
        print(fmt(stat, "PPL"))
    elif "avg_ppl" in data:
        print(f"  avg_ppl (precomputed): {data['avg_ppl']:.4f}")

    if "gar_recovery_pp" in data:
        print(f"  gar_recovery_pp: {data['gar_recovery_pp']:.4f}")

    return per_conv


def process_steering(data, fpath, n_boot, seed):
    """Process attention steering format (per-beta results)."""
    print(f"\n=== {Path(fpath).name} (attention steering) ===")
    for beta_key in sorted(data["results"].keys(), key=lambda k: float(k.split("_")[1])):
        bd = data["results"][beta_key]
        beta = bd["beta"]
        print(f"\n  --- beta={beta} ---")

        if "per_conv_mid_gar" in bd:
            vals = bd["per_conv_mid_gar"]
            stat = bootstrap_ci(vals, n_boot=n_boot, seed=seed)
            print(fmt(stat, "mid-turn GAR"))
        elif "gar_curves" in bd:
            per_conv = extract_per_conv_mid_gar(bd)
            if per_conv:
                stat = bootstrap_ci(per_conv, n_boot=n_boot, seed=seed)
                print(fmt(stat, "mid-turn GAR (from curves)"))

        if "ppl_per_conversation" in bd:
            stat = bootstrap_ci(bd["ppl_per_conversation"], n_boot=n_boot, seed=seed)
            print(fmt(stat, "PPL"))
        elif "avg_ppl" in bd:
            print(f"    avg_ppl: {bd['avg_ppl']:.4f}")

        if "mid_turns_avg_gar" in bd:
            print(f"    mid_turns_avg_gar (precomputed): {bd['mid_turns_avg_gar']:.6f}")
        if "mid_gar_std" in bd:
            print(f"    mid_gar_std (precomputed): {bd['mid_gar_std']:.6f}")


def process_phase1(data, fpath, n_boot, seed):
    """Process phase 1 diagnostic format (conversations[].gar_per_turn)."""
    print(f"\n=== {Path(fpath).name} (phase 1) ===")
    per_conv = []
    for conv in data["conversations"]:
        turns = conv["gar_per_turn"]
        if len(turns) >= 3:
            per_conv.append(float(np.mean(turns[2:])))

    if per_conv:
        stat = bootstrap_ci(per_conv, n_boot=n_boot, seed=seed)
        print(fmt(stat, "mid-turn GAR (per-conv)"))

    if "mid_turns_avg_gar" in data:
        print(f"  mid_turns_avg_gar (precomputed): {data['mid_turns_avg_gar']:.6f}")
    if "relative_drop" in data:
        print(f"  relative_drop: {data['relative_drop']:.4f}")


def process_file(fpath, n_boot, seed):
    """Auto-detect format and process."""
    with open(fpath) as f:
        data = json.load(f)

    if "conversations" in data and isinstance(data["conversations"], list) and \
       data["conversations"] and "gar_per_turn" in data["conversations"][0]:
        process_phase1(data, fpath, n_boot, seed)
    elif "results" in data and isinstance(data["results"], dict):
        first_key = next(iter(data["results"]))
        if first_key.startswith("beta_"):
            process_steering(data, fpath, n_boot, seed)
        else:
            process_standard(data, fpath, n_boot, seed)
    elif "gar_curves" in data:
        return process_standard(data, fpath, n_boot, seed)
    else:
        print(f"\n=== {Path(fpath).name} (unknown format) ===")
        print(f"  keys: {list(data.keys())}")
        for k, v in data.items():
            if isinstance(v, (int, float)):
                print(f"  {k}: {v}")


def main():
    parser = argparse.ArgumentParser(description="Bootstrap 95% CI for GAR eval results")
    parser.add_argument("files", nargs="+", help="Eval result JSON files")
    parser.add_argument("--n-boot", type=int, default=10000)
    parser.add_argument("--seed", type=int, default=42)
    parser.add_argument("--ci", type=int, default=95)
    args = parser.parse_args()

    for fpath in args.files:
        try:
            process_file(fpath, args.n_boot, args.seed)
        except Exception as e:
            print(f"\n=== {fpath} === ERROR: {e}")


if __name__ == "__main__":
    main()
